import java.util.*;
import java.io.*;

public class Main {
    static long[] fallingSquares(long[] left, long[] side) {
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] left = new long[n], side = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); left[i] = (long) in.nval;
            in.nextToken(); side[i] = (long) in.nval;
        }
        long[] res = fallingSquares(left, side);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
